interventions.example:
dc.create_direct_channel('coding-team-1')
dc.send_direct('coding-team-1', 'info', {
    'event': 'coordinator-clarification',
    'message': 'For the stress tests, use the existing test fixtures in tests/conftest.py. Do not create new database instances.',
    'priority': 'high'
})

# Write pointer to scratchpad
sp.write('think-tank-1-results', {
    'file_path': 'storage/coordination/teams/think-tank-1/output/analysis.json',
    'summary': 'Stress analysis complete. 11 failure modes identified.',
    'produced_by': 'think-tank-1',
    'available_since': time.time()
}, namespace='global', ttl=7200)

# Notify the waiting agent
dc.send_direct('coding-team-2', 'info', {
    'event': 'data-available',
    'scratchpad_key': 'think-tank-1-results',
    'description': 'Think tank analysis is ready for your stress test implementation'
})
